import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"OmniScript: Towards Audio-Visual Script Generation for Long-Form Cinematic Video","description":"","frontmatter":{"title":"OmniScript: Towards Audio-Visual Script Generation for Long-Form Cinematic Video","arxiv":"2604.11102","date":"2026-04-13","authors":"Junfu Pu, Yuxin Chen, Teng Wang, Ying Shan","categories":"cs.CV, cs.MM","topics":"智能体视频生成, 视频转剧本, 全模态长视频理解","outline":[2,2]},"headers":[],"relativePath":"papers/2604.11102.md","filePath":"papers/2604.11102.md","lastUpdated":null}'),l={name:"papers/2604.11102.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="omniscript-towards-audio-visual-script-generation-for-long-form-cinematic-video" tabindex="-1">OmniScript: Towards Audio-Visual Script Generation for Long-Form Cinematic Video <a class="header-anchor" href="#omniscript-towards-audio-visual-script-generation-for-long-form-cinematic-video" aria-label="Permalink to &quot;OmniScript: Towards Audio-Visual Script Generation for Long-Form Cinematic Video&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2604.11102" target="_blank" rel="noreferrer">2604.11102</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-04-13</td></tr><tr><td><strong>作者</strong></td><td>Junfu Pu, Yuxin Chen, Teng Wang, Ying Shan（腾讯 ARC Lab）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.MM</td></tr><tr><td><strong>一句话</strong></td><td>定义 video-to-script 任务，用带角色档案记忆的自动标注管线造数据，训一个 8B 音视频模型把长片逐场逐事件写成带时间戳的结构化剧本（角色、动作、表情、台词、音效）。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文提出 <strong>video-to-script（V2S）</strong>：输入几分钟到几十分钟的影视视频，输出分层的结构化剧本。层次是 Meta（标题、时长、角色表）到 Scene（场景 ID、地点、日夜）再到 Event，每个事件形式化为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，即时间戳、角色、台词、动作、表情、音效线索。</p><p>工业侧的价值是自动打点、内容检索、辅助创作。研究侧更关键：它把长视频理解从模糊的问答与摘要变成一个<strong>有稠密结构、可逐字段评分</strong>的任务。benchmark 平均每分钟标注 14.1 个事件，相当于每 4 秒锚定一个叙事动作，这个密度封死了靠稀疏抽帧蒙混的路。作者列了三个障碍：标注长片成本极高；开放式长文本无法用 BLEU 或 ROUGE 衡量；两分钟片段就要约 4000 token，长片推理开销会爆炸。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>影视理解线</strong>从短片段描述（MPII-MD、MAD）到剧情推理（MovieQA），再到结构化标注（AVA、MovieGraphs、MovieNet）。作者指出一个持续存在的二分：宏观剧情分析缺细粒度时间锚定，结构化标注产不出可读的连贯叙事。Movie101 能做角色感知的解说，但仍主要处理孤立、无对白的片段。</p><p><strong>稠密与全模态描述线</strong>中，传统 dense video captioning 定位显著事件但输出稀疏；AVoCaDO、video-SALMONN-2 做到了深度多模态融合，却是整体性描述、没有显式时间锚定。同期的 TimeChat-Captioner 提出 Omni Dense Captioning，做到场景级带时间戳描述，但角色动作、意图、对白仍纠缠在粗粒度摘要里。</p><p>OmniScript 的差异化是强制 <strong>Scene → Event → Field</strong> 的解耦层级：动作是动作、表情是表情、台词是台词、音效是音效，各自独立成字段并锚定到稠密时间戳。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>数据是第一道坎。人工标注长片不可行，而把长片切段各自独立标注再拼接会在角色身份上崩掉——影片里区分角色的线索是多模态的（声音、步态、服装），不是单靠人脸。于是需要一个跨段的<strong>角色档案记忆</strong>：标注第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 段时注入历史档案，让模型显式给出匹配置信度与依据；对未报名字的角色先用临时 ID，等对白里出现确定称呼再回溯升级并合并重复记录（论文称 lazy naming）。</p><p>第二道坎是评测。事件是开放词表的，预测时间戳会有几秒偏移。按 tIoU 匹配会把语义正确但延迟三秒的预测判为完全失败；只算文本相似度又会让模型不管时间。合理的拆法是<strong>先按文本对齐、再单独评时间</strong>。角色名同样开放词表（GT 是&quot;John&quot;，预测是&quot;警察&quot;），所以字段评分之前必须先建立统一的角色语义空间。</p><p>第三道坎是长度。5 分钟以内单次生成可行，更长必须在&quot;扩上下文窗口&quot;与&quot;先分段规划再分段写作&quot;之间选择，论文把两条路都实现了并直接对比。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>长片理解的瓶颈不是看不清画面，而是<strong>跨越几十分钟维持&quot;谁是谁&quot;</strong>。把角色身份提取成显式、可更新、可回溯改名的外部档案，长视频标注就从&quot;一次性理解全片&quot;退化成&quot;逐段理解加记忆查询&quot;。评测同理：先用文本对齐把&quot;哪个预测对应哪个真值&quot;独立解掉，语义正确性与时间准确性才能各自被公平度量。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>数据引擎。</strong> 用 PySceneDetect 把 1 万多部原始影视切成约 4.5 万个 5 分钟以内的语义片段。每段用 Gemini-2.5-Pro 做角色中心的剧情推理，条件是档案管理器里检索出的历史档案，同时把服装变化等新属性写回。拿到全局一致的剧情描述后，与原始音视频一起送进 Gemini 生成细粒度剧本。最后用 DeepSeek 从剧本反向蒸馏&quot;中间思考&quot;，得到 Video 到 Thinking 再到 Script 的 CoT 数据集。</p><p><strong>模型。</strong> 骨干 Qwen3-VL-8B，音频编码器 Whisper large-v3。每个时间单元构造配对表示 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 保证画面与声音在时间戳级对齐。AV-DeepStack 把音频与视觉 token 成对注入多个 transformer 层而非只在输入层，让语言流在深层推理时反复与两个模态交互。解码时先输出推理轨迹（剧情推进摘要与角色关系状态），再由粗到细生成剧本字段。</p><p><strong>四阶段训练。</strong> 一是模态对齐：约 100 万条中英双语带时间戳 ASR 样本，只训音频投影器、冻结 Whisper 与 ViT 与 LLM，并随机遮挡视频帧逼模型用音频。二是多模态预训练：240 万条领域内视频全量微调，多任务含 ASR（带与不带时间戳）、摘要、稠密描述、时序定位。三是 SFT：4.5 万条视频（2.1 万横屏影视加 2.4 万竖屏短剧），CoT 格式，随机遮挡字幕以降低对显式文本的依赖。四是 RL：用 GRPO，奖励直接取评测框架里的多维字段得分，即<strong>时间分段奖励</strong>，避免全局语义相似度掩盖短事件上的细微错误。</p><p><strong>长视频两条路。</strong> LCE 直接扩上下文，训练时用跨视频拼接造伪长视频与伪剧本；TSG 先训一个剧情分段模型预测每段的时间戳、剧情、角色表与关系，再逐段生成、最后合并并做一致性后处理。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>评测框架是数学含量最高的部分。<strong>阶段一</strong>按复合文本分对齐事件：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.075em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2074em;vertical-align:-0.836em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.075em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">dialogue</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.075em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">action</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">5.0</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3.0</span></span></span></span></span></p><p>两个相似度都用归一化 Levenshtein 距离，台词权重高于动作因为字面可比性更强。再加一个上限很低的时间奖励作为平局打破：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0503em;vertical-align:-0.367em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.075em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">time_bonus</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.367em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4em;vertical-align:-0.95em;"></span><span class="mop">min</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">(</span></span><span class="mord">0.1</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">exp</span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">(</span></span><span class="mord">−</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">15.0</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">Δ</span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">m</span><span class="mtight">i</span><span class="mtight">n</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">)</span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">0.1</span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">)</span></span></span></span></span></span></span></p><p>配对还要满足时间距离不超过 30 秒，最终用动态规划求解一个加权区间调度问题，在&quot;真值与预测下标都不重叠、时序严格保持&quot;的约束下最大化总对齐分。</p><p><strong>阶段二</strong>解析角色。LLM 先把名字分成专名、单数身份名、复数身份名并给出初始二部映射，剩下的用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.075em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fallback</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord">0.5</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord text"><span class="mord">IoU</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">temporal</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord">0.5</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord text"><span class="mord">Sim</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 贪心匹配，阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span>，且禁止专名互配、专名与复数身份互配、单复数身份互配。</p><p><strong>阶段三</strong>逐字段评分：角色精确匹配，台词用 Levenshtein，动作、表情、音效交给 LLM 判官打 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，一对多时贪心取最大相似度。精确率与召回率的分母<strong>不对称</strong>：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Precision</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4133em;vertical-align:-1.053em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pred_total</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.367em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.075em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">total</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.053em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">Recall</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4133em;vertical-align:-1.053em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gt_total</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.367em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathcal" style="margin-right:0.075em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.075em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">total</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.053em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>召回分母是整份真值剧本的全部条目（含完全漏检的），漏检因此被严格惩罚。<strong>推测</strong>：正文对精确率分母的表述存在张力——阶段一说未对齐的预测组会降低精确率，阶段三却把分母定义为&quot;所有<strong>已对齐</strong>预测组的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pred</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 之和&quot;，按后者字面理解，完全对不上任何真值的捏造事件不会进入字段精确率的分母。<strong>阶段四</strong>独立评时间，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">time</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">@</span><span class="mord mathnormal">t</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">time</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">@</span><span class="mord mathnormal">t</span></span></span></span> 取调和平均得 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">t</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mord mathnormal">o</span><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="mord">@</span><span class="mord mathnormal">t</span></span></span></span>。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>8B 能否顶住？</strong> 5 分钟片段的事件级结果里 OmniScript 拿到 Overall 37.7、tIoU@0.1 69.3，明显超过 Qwen3VL-235B-A22B 的 33.0 与 62.0。与闭源模型要分开看：台词 F1 72.2 高于 Gemini-3-pro 的 68.8 与 Seed-2.0-pro 的 68.1，时序定位 69.3 也高于两者的 64.4 与 67.1；但 Gemini-2.5-flash（43.6、74.3）与 Gemini-2.5-pro（42.9、73.4）在综合分上明显领先。摘要里&quot;与 Gemini 3-Pro 相当&quot;对 3 系成立、对 2.5 系不成立。另外正文 6.2 节引用的是 37.0 与 69.0，与表 1 的 37.7 与 69.3 不一致，前者对应消融表里去掉 CoT 的那一行。一个所有模型都失败的字段是音效：OmniScript 11.6、Gemini-3-pro 13.3、Qwen3VL 低至 6.0，最好的反而是分段送入的 TimeChat-Captioner（25.4）。</p><p><strong>CoT 与分段奖励各值多少？</strong> SFT 基线 Overall 35.3、tIoU 66.6；加 CoT 到 37.0、68.9，台词从 68.2 到 71.0；再加 GRPO 且用分段奖励到 37.7、69.3；换成全局奖励则回落到 37.0。</p><p><strong>是不是在读字幕作弊？</strong> 遮挡字幕后 Qwen3VL-235B 的台词 F1 从 58.6 崩到 7.7，Gemini-3-pro 从 68.8 降到 60.9，OmniScript 从 72.2 降到 63.8。这条实验有力地区分了&quot;真的在听&quot;与&quot;在抄画面上的字&quot;。配套的纯视觉消融显示同样数据下不给音频的模型台词只有 52.0、Overall 31.1，给音频则是 68.2 与 35.3；但 tIoU 反而从 68.2 掉到 66.6，<strong>推测</strong>音频通路对时间戳预测有轻微干扰，论文未讨论。</p><p><strong>长片怎么办？</strong> 10 到 45 分钟的评测显示 30 分钟处存在一道上下文悬崖：Gemini 系列与自家的 LCE 在几乎所有维度上体积性坍缩；Gemini-2.5-flash 在 25 分钟以下靠高召回反超更强型号，超过后退化成重复生成循环。相比之下 TSG 的曲线近乎水平。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版。</strong> OmniScript 定义了 video-to-script 任务，输出三层、每个事件含时间戳与五个解耦字段的结构化剧本。数据靠一条带角色档案记忆的自动标注管线产出，核心是跨段身份追踪与 lazy naming 回溯改名。评测框架把语义与时间解耦成四阶段：文本对齐（DP 求加权区间调度）、LLM 角色映射、逐字段打分、独立 tIoU 命中率。模型是 Qwen3-VL-8B 加 Whisper，用 AV-DeepStack 多层注入音视频 token，经模态对齐、240 万预训练、CoT SFT、分段奖励 GRPO 四阶段训练。8B 规模超过 Qwen3VL-235B 并在台词与时序定位上胜过 Gemini-3-pro，但综合分低于 Gemini-2.5 系列；两阶段的 TSG 在 30 分钟以上呈现长度不变性。</p><p><strong>三句话版。</strong> 长片理解的真正瓶颈是跨段角色身份，把它做成显式可更新的外部记忆就能规模化产数据。评测必须先按文本对齐再单独评时间，否则语义与定位互相污染。8B 全模态模型能打过 235B 视觉模型，字幕遮挡实验证明增益来自真听音频而非抄字幕。</p><p><strong>一句话版。</strong> 把长片翻译成带时间戳的结构化剧本，靠角色档案记忆解决数据，靠四阶段解耦框架解决评测。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是：<strong>模型在环的标注（自动伪标签加人工精修加专家复核）能够消除教师模型的系统性偏差</strong>。训练数据全部由 Gemini 生成，benchmark 的初始稠密伪标签也出自同一套引擎再交标注员精修。模型有效与 benchmark 可信这两个核心 claim 同时依赖这条。</p><p>为什么可能不成立？人工精修能修正<strong>已写出的</strong>条目（改错时间、改错名字），却很难补上教师模型<strong>从未提出过</strong>的整类事件。如果 Gemini 系统性忽略某类线索（例如非语言音效，或没有对白的纯动作过场），这类事件既不在训练数据里也不在 GT 里，模型学不到、评测也不扣分。</p><p>证据两头都有。支持的一侧是确有专家逐份复核，交叉验证时间边界与长程语义一致性。与担忧一致的信号有两个：音效字段所有模型分数都极低（6 到 25），而唯一最高的 TimeChat-Captioner 恰恰不属于 Gemini 家族；以及 Gemini-2.5 系列在事件级综合分上排第一，而 benchmark 草稿正由 Gemini-2.5-Pro 生成。缺的是&quot;完全独立的从零人工标注&quot;子集来量化教师偏差的规模。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要训练模型，只需评测代码与若干模型输出。</p><ul><li><strong>数据</strong>：从 benchmark 取 20 个 5 分钟片段的 GT 与两个模型（一个 Gemini、一个开源）的预测输出。</li><li><strong>实现</strong>：写一个模糊化脚本，用 LLM 把预测里的 action 与 expression 字段改写成更笼统的表述（&quot;张三快步走到门口推门出去&quot;改成&quot;张三离开&quot;，&quot;愤怒、失望、痛苦&quot;改成&quot;负面情绪&quot;），台词、时间戳、角色不动。附录里的评分准则明确把这两类改写判为满分匹配。</li><li><strong>测量</strong>：对原始与模糊化输出分别跑完整评测，比较 Action F1、Expression F1 与 Overall 的变化，并统计判官的分数分布。</li><li><strong>判据</strong>：若模糊化后分数持平或上升，说明该指标系统性奖励含糊，排行榜差距有相当部分反映的是描述粒度偏好而非理解能力；若明显下降，则判官比准则文字更严格、指标稳健。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是指出 <strong>OmniScript 与 benchmark 的 GT 出自同一个生成分布</strong>。GT 初稿由 Gemini 产出，OmniScript 的训练数据也由 Gemini 产出，两者共享事件粒度、字段划分习惯、什么值得写进剧本的判断。任何没有被这条管线塑造过的模型（Qwen3VL、MiniCPM-O、TimeChat-Captioner）都会在事件切分粒度上系统性错配，而阶段一的对齐按文本相似度做，粒度错配会直接变成对齐失败，同时拉低精确率与召回率。</p><p>具体实验：请专业编剧对 10 个 5 分钟片段做<strong>从零人工标注</strong>，不给任何模型草稿，得到独立 GT，然后在两份 GT 上重跑所有模型。预测是 OmniScript 与 Gemini 家族在独立 GT 上的召回下降幅度显著大于其他模型，排名可能重排。若成立，&quot;8B 超过 235B&quot;应重述为&quot;8B 在教师分布上超过 235B&quot;。</p><p>第二个可预测的失败条件来自评测设计本身：阶段一要求对齐时时序严格保持且时间距离不超过 30 秒。对闪回、平行剪辑、非线性叙事这类结构，模型即使完全理解也可能给出与 GT 不同的事件排序，而 DP 的单调性约束会把这类正确理解判为漏检加幻觉。benchmark 覆盖了悬疑（19.5%）这种高频使用闪回的类型，但论文没有按叙事结构分层报告结果。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：OmniScript 是纯理解系统，剧本是终点。但它产出的东西——逐事件带时间戳、角色对齐、动作与音效解耦的结构化表示——恰好是视频<strong>生成</strong>侧最缺的那种细粒度、可解释、时间锚定的信号。目前长视频生成的奖励模型多半给一个全局标量，既不知道第 37 秒的动作错在哪，也无法定位是哪个角色的身份漂了。</p><p><strong>新的 framing</strong>：把剧本当作<strong>双向接口</strong>而非输出，研究 video 到 script 再到 video 的<strong>往返一致性</strong>。给定剧本生成视频，再用 OmniScript 把生成的视频解析回剧本，用同一套四阶段框架比较两份剧本。得到的不是一个标量，而是一张按字段、按时间戳分解的误差表：哪几秒的动作没执行、哪个角色在第几个事件后换了脸、哪段音效缺失。这把视频质量评估从整体打分变成可定位的结构化诊断。</p><p><strong>可借鉴的相邻工具</strong>：一是把推理与打分解耦的视频奖励模型思路，用往返剧本差异作为可验证奖励接进 GRPO 这类算法；二是编译器领域的往返测试方法论，那里已系统研究过&quot;解析、生成、再解析&quot;不动点的性质与失效模式。</p><p><strong>第一个实验</strong>：取 200 段真实影片片段，用 OmniScript 解析出 GT 剧本，喂给一个开源长视频生成模型，再解析回来算往返字段 F1 与 tIoU，同时收集人类对生成视频的成对偏好。核心假设是<strong>往返剧本 F1 与人类偏好的相关性是否高于现有的全局视频奖励模型</strong>。若显著更高，理解模型就可以直接充当生成模型的稠密奖励与调试器，V2S 的价值从看懂电影扩展到造出电影。</p>',56)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
